'use strict';
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
let mode = 'cli';
let component = 'adapter';
const components = {
  adapter: {kind:'01 / EVOLVED REPO',title:'Harness Adapter',description:'The entire evolvable core repo: knowledge, prompts, Python capabilities, roles, and declarations. Every core file may change; the framework supplies the wrapper outside this repo.',items:['Editable content and context rendering','Ordinary callables plus editable schemas','Optional native role definitions'],boundary:'No adapter-owned MCP server. Candidates must satisfy the external contract, not preserve a frozen set of internal files. MWM is one method-specific core.'},
  acting: {kind:'02 / TASK EXECUTION',title:'Acting Harness',description:'The existing environment running the parent agent. It loads native role definitions, runs user tasks, and carries out delegation decisions.',items:['Use the adapter through context and MCP','Load native role settings prepared before startup','Create, run, and manage child instances on demand'],boundary:'Definitions stay fixed for the run; instances and tasks are dynamic. The adapter runs the 4B helper as a tool.'},
  metaharness: {kind:'03 / LEARNER EXECUTION',title:'Meta Harness',description:'The meta-agent execution environment: read experience, edit the repo, run tools, and check changes.',items:['Expose permitted experience and files to the learner','Support code edits, tool calls, and checks','Help the Evolver produce the next candidate revision'],boundary:'Meta Harness is the execution environment; Evolver is the learning algorithm. Methods need not share an update procedure.'},
  runtime: {kind:'SUPPORT / TOOL EXECUTION',title:'Framework Runtime',description:'The shared loader wraps declared core functions as MCP tools. It owns protocol handling, input/output validation, invocation logs, and explicit resource bindings.',items:['Discover callables from adapter.json','Expose added tools without editing the wrapper','Keep audit logs and deployment files outside core'],boundary:'Framework-owned infrastructure, outside the learner write surface. The initial runtime executes trusted Python code; this is not an OS sandbox.'},
  evolver: {kind:'SUPPORT / LEARNING METHOD',title:'Evolver',description:'The reusable update algorithm. Each iteration returns an Adapter and optional Training State; stateless methods return no state.',items:['Read supplied experience and the complete candidate core','Edit any core file through bounded workspace tools','Return a candidate and optional Training State (protocol design)'],boundary:'The corrected MWM method retains the original contract, skills, patterns, docket and journal policy. Experience and method material are read-only; executable admission requires the sandbox.'},
  connector: {kind:'SUPPORT / BOOTSTRAP',title:'Bootstrap / Connector · Optional',description:'Integration helpers used as needed. Hosts, users, and external frameworks can configure the three interfaces directly.',items:['Prepare Markdown context and MCP connections','Convert optional roles: name / description / instructions','Start the host, verify loading, then begin formal tasks'],boundary:'The helper is optional; host integration requirements still apply. Definitions stay fixed for the run without depending on hot loading.'},
  manager: {kind:'APP / ORCHESTRATION',title:'Default Manager',description:'Default CLI orchestration, optionally using integration helpers and organizing subsequent evolution from experience.',items:['Coordinate preparation and run records','Trigger the Evolver and organize checks and evaluation','Decide whether a candidate enters the next deployment'],boundary:'Candidate changes do not replace loaded roles. When an external framework orchestrates updates, it retains final release authority.'}
};
function renderComponent(name) {
  component=name;
  const d=name==='manager'&&mode==='reef'?{kind:'FRAMEWORK / ORCHESTRATION',title:'Reef Orchestrator',description:'An external framework retains the update loop while using adapter, preparation, and evolution capabilities from the same SDK.',items:['Reef selects experience and triggers learning','The integration converts candidates and delivers revisions','Reef evaluates, selects, and schedules the next deployment'],boundary:'Reef integration remains a design goal. Conversion between tree mutations and independent repos needs implementation and verification.'}:components[name];
  $$('.component-node').forEach(n=>{const selected=n.dataset.component===name;n.classList.toggle('selected',selected);n.setAttribute('aria-pressed',String(selected));});
  $('#detail-kind').textContent=d.kind;$('#detail-title').textContent=d.title;$('#detail-description').textContent=d.description;
  $('#detail-list').replaceChildren(...d.items.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));$('#detail-boundary').textContent=d.boundary;
}
function setMode(value){
  mode=value;
  $$('[data-mode]').forEach(b=>{const selected=b.dataset.mode===value;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});
  $('#manager-title').textContent=value==='cli'?'Default Manager':'Reef Orchestrator';
  $('#manager-sub').textContent=value==='cli'?'CLI update orchestration':'External update orchestration';
  $('#invocation-label').textContent='Trigger Evolver';
  $('#ownership-text').textContent=value==='cli'?'The CLI uses the public SDK with existing integration or optional helpers. The default Manager organizes evolution; new roles load in the next run.':'Reef uses the same SDK and retains orchestration. It can handle integration directly or use an optional Connector. Our Manager does not make a second release decision.';
  renderComponent(component);renderStage(stage);renderEntry(value,false);
}
$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));
$$('.component-node').forEach(n=>{n.addEventListener('click',()=>renderComponent(n.dataset.component));n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();renderComponent(n.dataset.component);}});});

const templates={
  "skill": {
    "title": "prompt-only/",
    "kind": "IMPLEMENTED ARCHITECTURE",
    "description": "A context-only architecture. No learned instructions initially, no native roles, and no adapter MCP server. Choose the Evolver separately.",
    "tags": [
      "context only",
      "no MCP server",
      "empty learned prompt"
    ],
    "files": {
      "adapter.json": "{\n  \"contract\": \"harnessadapter.python.v1\",\n  \"id\": \"prompt-only\",\n  \"name\": \"Prompt-only Architecture\",\n  \"version\": \"0.1.0\",\n  \"context\": \"ADAPTER.md\",\n  \"evolver_readme\": \"EVOLVER.md\",\n  \"tools\": []\n}\n",
      "ADAPTER.md": "# Adapter context\n\nNo learned instructions yet.\n",
      "EVOLVER.md": "# Prompt-only evolution guide\n\nThis architecture starts with one empty learned-context document, ADAPTER.md.\nThe acting harness receives that document as context. No adapter MCP server or\nnative subagent is registered while tools and agents are absent.\n\nUse the supplied evidence README to understand the records. Update ADAPTER.md\nwith instructions useful for future tasks. Do not invent findings or represent\na single observed case as a universal rule. Explain your changes in your report.\nDo not copy private raw histories into the acting context unnecessarily.\n\nFor a prompt-only experiment, keep tools empty and omit agents. This is the\nexperiment's chosen search space, not a framework restriction: a different\nexperiment can evolve code, tools, roles, and declarations too.\n\nAll files in the candidate are editable. Framework infrastructure and evidence\nremain outside the candidate. This architecture does not implement GEPA or\nSkillOpt; choose or supply an Evolver separately. Structural checks do not\nestablish that the new instructions improve task performance.\n",
      "README.md": "# Prompt-only Architecture\n\nAn initial adapter structure with no learned task knowledge. The acting export\nis ADAPTER.md; tools and native roles are absent. The framework does not register\nor start an adapter MCP server for this architecture.\n\nFrom the framework root, evolve a separate candidate:\n\n```sh\n./harnessadapter evolve --architecture prompt-only \\\n  --evidence fixtures/mwm_evidence \\\n  --prompt \"Read the evidence and write useful, scoped instructions in ADAPTER.md.\"\n```\n\nThe result reports a candidate directory. Deploy that directory:\n\n```sh\n./harnessadapter deploy /path/from/result/adapter --host codex\n```\n\nFor an empty-context integration check, deploy the built-in architecture directly:\n\n```sh\n./harnessadapter deploy prompt-only --host claude-code\n```\n\nThe built-in source is never overwritten by evolution. No optimizer-specific\nalgorithm or validation procedure is implied by the architecture.\n"
    }
  },
  "knowledge": {
    "title": "examples/mwm_adapter/",
    "description": "Corrected MWM core: original artifact bundles, empty learned tools and roles, one wm interface, and persistent cases separate from the journal. Generic transport stays in the framework.",
    "tags": [
      "original MWM structure",
      "single wm interface",
      "sandbox-gated programs"
    ],
    "files": {
      "adapter.json": "{\n  \"contract\": \"harnessadapter.python.v1\",\n  \"id\": \"mwm\",\n  \"name\": \"mwm\",\n  \"version\": \"mwm-structure-v2\",\n  \"context\": {\n    \"entrypoint\": \"interface.py:context\"\n  },\n  \"agents\": {\n    \"entrypoint\": \"interface.py:agent_definitions\"\n  },\n  \"resources\": {\n    \"evidence\": {\n      \"required\": false,\n      \"access\": \"read\"\n    }\n  },\n  \"tools\": [\n    {\n      \"name\": \"wm\",\n      \"description\": \"The MWM world model: memory, recall, trace, search, read, list, and admitted learned tools through wm(name, args). run requires the framework sandbox; delegate gives native-host guidance.\",\n      \"entrypoint\": \"interface.py:wm\",\n      \"input_schema\": {\n        \"type\": \"object\",\n        \"properties\": {\n          \"name\": {\n            \"type\": \"string\"\n          },\n          \"args\": {\n            \"type\": \"object\"\n          }\n        },\n        \"required\": [\n          \"name\"\n        ],\n        \"additionalProperties\": false\n      },\n      \"output_schema\": {\n        \"type\": \"object\"\n      },\n      \"annotations\": {\n        \"readOnlyHint\": true,\n        \"destructiveHint\": false,\n        \"idempotentHint\": true,\n        \"openWorldHint\": false\n      }\n    }\n  ],\n  \"evolver_readme\": \"EVOLVER.md\"\n}\n",
      "ADAPTER.md": "# MetaWorld Model adapter\n\nThis core preserves MWM's V2 default artifact structure. Its live Context is rendered by interface.py using the five-part MWM package: host framing, briefing, open questions, memory catalog, and access instructions. This file documents the adapter; it is not a replacement briefing.\n\nAll host access uses one wm(name, args) tool. Learned tools remain tools/<name>/{TOOL.md,run.py,test.py}; hosts call wm(name=<SCHEMA name>, args=...). Programs are discovered statically and admitted only after their tests pass in the framework sandbox. Without that sandbox they remain unavailable, with TOOL.md as the prose fallback. No learned program is imported into the wrapper process.\n\nRoles retain agents/<name>/SPEC.md. Only templates are seeded, not a pre-made researcher. The export bridge translates discovered specs into the framework's role contract for native Codex or Claude Code registration.\n\nKnowledge is prose under memory/. Worked examples under examples/ link derived_from addresses to raw evidence supplied outside the core. trace uses record addresses such as q17 and the original turn-index argument `from`, not arbitrary file paths and character offsets. read uses /world-model/... paths.\n\nThe docket under meta/cases/ persists independently of journal rolling. The MWM Evolver retains the original contract, agenda, skills, patterns, and method-specific maintenance outside the editable core. All files inside this core remain evolvable under the new framework boundary.\n",
      "EVOLVER.md": "# Evolution guide: MetaWorld Model\n\nThis document is for the Evolver, not the acting host. The live acting context is rendered from the MWM package; ADAPTER.md documents that surface. This guide belongs to the evolvable core and does not grant permissions.\n\n## What this adapter maintains\n\nA world model of an external environment: scoped and dated knowledge, its grounding in worked examples, unresolved investigations, and justified executable capabilities. The original V2 default has a persistent docket and a rolling journal; it does not seed learned roles or tools.\n\n## Structure\n\n- memory/<topic>.md: prose knowledge with brief, scope, last_confirmed_t, derived_from, and optional open fields.\n- examples/<record-address>.md: authored worked examples grounding those claims.\n- tools/<name>/{TOOL.md,run.py,test.py}: learned programs with literal SCHEMA and run(**kwargs), admitted only after sandboxed tests.\n- agents/<name>/SPEC.md: role trigger, scope, dates, provenance, and instructions. The framework converts these for the acting host.\n- consumption/brief.md: the current briefing; host delivery applies the original cap.\n- meta/cases/: unresolved investigations that persist until settled.\n- meta/journal.md and its archive: session records with separate rolling behavior.\n- interface.py and mwm_core/: method-specific consumption and dispatch code.\n- adapter.json: the public loading contract; hosts use a single wm(name,args) tool.\n\n## Evidence and evolution\n\nThe evidence store lives outside this adapter and is always read-only. Its README.md defines the available record format, logical addresses, timing, feedback, and access limitations. Do not assume every store has the synthetic demo's layout. Keep derived_from links resolvable through worked examples and original records.\n\nWhen using the MWM Evolver, read the full method contract, agenda, and referenced skills/patterns. Repair old claims before acquiring new ones; only increase last_confirmed_t when observations support the claim. Preserve historical validity and uncertainty. Maintain the docket separately from journal entries. Update the briefing and verify every promised access path.\n\nAll core files may evolve, including this guide and the consumption implementation. Changes must preserve the declared public contract or update it coherently. User-defined environment reads and networking are supplied by framework policy. Read environment/README.md or call get_policy; this document cannot expand those permissions. An unavailable sandbox is not a passing executable admission test.\n",
      "interface.py": "\"\"\"MWM export bridge. The method keeps its original artifact structures and wm API.\"\"\"\nfrom pathlib import Path\n\nfrom .mwm_core import capabilities, delegate\nfrom .mwm_core.wm_iface import WorldModelInterface\n\nROOT = Path(__file__).resolve().parent\n\n\nclass Interface(WorldModelInterface):\n    def __init__(self, resources):\n        self.evidence_bound = resources.get('evidence') is not None\n        evidence = str(resources['evidence'].root) if self.evidence_bound else str(ROOT/'_no_evidence_binding')\n        sandbox = resources.get('python_sandbox')\n        super().__init__(str(ROOT), evidence, delegation='native',\n                         code_channel=bool(sandbox and sandbox.status()['available']))\n\n    def _trace_pointer(self, address):\n        return super()._trace_pointer(address) if self.evidence_bound else ''\n\n    def _run_tool(self, name, args):\n        if name in {s['name'] for s in capabilities.candidates(str(ROOT))}:\n            ok,reason = capabilities.run_test(str(ROOT),name)\n            if not ok:return f'{name}: not admitted — {reason}. Read tools/{name}/TOOL.md for the prose fallback.'\n        return super()._run_tool(name,args)\n\n\ndef context(_resources=None):\n    resources=_resources or {};token=capabilities.RESOURCES.set(resources)\n    try:\n        text=Interface(resources).package('The host exposes the single wm(name, args) tool through MCP. Native roles come from agents/<name>/SPEC.md; no role is seeded by default.')\n        sandbox=resources.get('python_sandbox')\n        if sandbox is None or not sandbox.status()['available']:\n            text+='\\n\\nExecution availability: the required sandbox is unavailable. Learned programs are not admitted or executed; use their TOOL.md prose fallback. wm run is unavailable.'\n        return text\n    finally:capabilities.RESOURCES.reset(token)\n\n\ndef agent_definitions():\n    return [{'name':name,'description':description,'instructions':f'agents/{name}/SPEC.md'}\n            for name,description in delegate.list_specs(str(ROOT))\n            if (ROOT/'agents'/name/'SPEC.md').resolve().is_relative_to(ROOT)]\n\n\ndef wm(name: str, args: dict | None = None, _resources=None) -> dict:\n    resources=_resources or {};args=args or {}\n    if name.strip().lower()=='trace' and 'evidence' not in resources:\n        return {'text':'trace: no evidence resource is bound for this deployment'}\n    if name in ('memory','recall'):\n        address=str(args.get('id' if name=='memory' else 'address',''))\n        if '/' in address or '\\\\' in address or address.startswith('.'):\n            return {'text':'invalid memory or record address'}\n    token=capabilities.RESOURCES.set(resources)\n    try:return {'text':Interface(resources).call(name,args)}\n    finally:capabilities.RESOURCES.reset(token)\n",
      "memory/_template.md": "last_confirmed_t: 0\nscope:\nderived_from:\nbrief:\n\n<the entry in plain language>\n",
      "examples/_template.md": "input: <what the episode was given, verbatim enough to recognise it again>\noutcome: <how it ended, in the environment's own terms>\nlast_confirmed_t: <tick>\nscope: <what this example does and does NOT settle>\nderived_from: self (this IS the record)\n\nDecisive: <the interpretation choices that settled it — which reading of\nthe input, which boundary, which tie-break rule, and why that one>\nSkeleton: <the action or computation that was accepted, trimmed to its\ndecisive shape>\nFeedback: <what the environment said back, if it says anything — and what\nthat implies about the environment, stated so the next solver can apply it\ndirectly>\n",
      "tools/_template/TOOL.md": "<first line: trigger>\nscope:\nlast_confirmed_t:\nderived_from:\nrepairs: 0\n\n## Invocation\n\n## Verification\n",
      "tools/_template/run.py": "SCHEMA = {\"name\": \"<tool_name>\", \"description\": \"<what it does, when to call it>\",\n          \"parameters\": {\"type\": \"object\", \"properties\": {}, \"required\": []}}\n\ndef run(**kwargs):\n    \"\"\"Stdlib-only. Executes only through the framework sandbox resource.\"\"\"\n    raise NotImplementedError\n",
      "tools/_template/test.py": "\"\"\"Admission test; never run in the host wrapper process.\"\"\"\nimport run\nassert run.SCHEMA[\"name\"] != \"<tool_name>\"\n",
      "agents/_template/SPEC.md": "<first line: when to delegate to this, in trigger words>\nscope: <where this applies>\nlast_confirmed_t: <block>\nderived_from: <the episodes that showed hosts working through this sub-problem>\n\n<the sub-agent's prompt: what it works on, how it proceeds, what it\nhands back and in what form, when to report \"not applicable here\">\n",
      "consumption/brief.md": "# Environment briefing\n\n(Nothing has been learned about this environment yet; what is learned from\ncompleted episodes will appear here.)\n",
      "meta/cases/README.md": "One OPEN CASE per file, named NN-<slug>.md (two-digit\nid, assigned once; deleting the file closes the case and retires the\nnumber). A case is a question awaiting settlement: an unresolved\ninterpretation, a candidate list under narrowing, a watch that a\nspecific future episode can settle. State what is open, the candidates\nand their status, and what evidence would settle it. Rewrite in place\nas the investigation moves; 3000 chars per case, ENFORCED — the wrapper\ntruncates an oversized case in place before each session (git keeps the\nfull text). At most 12 open cases: a full docket means close or merge\none first.\n\nClosing a case: write the settlement where it belongs (memory/ for\nfacts), leave a one-line closure in the session's journal entry, then\nDELETE the file — git keeps every version, deletion loses nothing.\n\nHow to run the docket — opening, advancing, the settling line in the\nbriefing, triage when full: /skills/keep-journal.\n\nNOT for: operations to run every session, settled\nfacts (memory/), host-facing knowledge (consumption/brief.md), session\nnarration (meta/journal.md).\n",
      "meta/journal.md": "# Journal — the session RECORD. Open questions live in\n# meta/cases/, one file each, never rolled.\n\nOne entry per session, headed `## Session <block>` with the bare block\nnumber (`## Session 7` — never `## Session block007`), first line\n`Digest: <one sentence>`. Then the update: section (what each failed episode showed, under which conditions, and what it changes), the observations, and one-line closures for settled cases\nAnything still OPEN belongs in meta/cases/, one file each, never rolled, not a paragraph here: this file's\nolder entries collapse to their Digest line after five sessions (full\ntext in meta/journal-archive.md), so an open question recorded only\nhere will be forgotten.\n\n## Older sessions (digests)\n"
    }
  },
  "helper": {
    "title": "search-helper/",
    "description": "An illustrative future core: a small-model helper is an ordinary declared capability. Model-resource binding is not implemented by the current Python prototype.",
    "tags": [
      "illustrative",
      "model resource required",
      "framework wraps call"
    ],
    "files": {
      "adapter.json": "{\n  \"contract\": \"harnessadapter.python.v1\",\n  \"name\": \"search-helper\",\n  \"version\": \"v1\",\n  \"context\": \"ADAPTER.md\",\n  \"resources\": {\n    \"small_model\": {\n      \"required\": true\n    }\n  },\n  \"tools\": [\n    {\n      \"name\": \"search_evidence\",\n      \"description\": \"Extract sourced evidence from search results.\",\n      \"entrypoint\": \"search.py:search_evidence\",\n      \"input_schema\": {\n        \"type\": \"object\",\n        \"properties\": {\n          \"query\": {\n            \"type\": \"string\"\n          }\n        },\n        \"required\": [\n          \"query\"\n        ]\n      },\n      \"output_schema\": {\n        \"type\": \"object\"\n      }\n    }\n  ]\n}",
      "ADAPTER.md": "# Search Helper\n\nUse search_evidence to preprocess search results and preserve sources. The parent agent remains responsible for the final answer. This core has no native role definitions.",
      "search.py": "# Illustrative resource API, not a runnable implementation.\nasync def search_evidence(query, _resources):\n    pages = await _resources[\"search\"](query)\n    return await _resources[\"small_model\"].extract(query, pages)\n\n# No MCP imports, decorators, or server startup here."
    }
  }
};
let activeTemplate='knowledge';let activeFile='adapter.json';
function showFile(path){activeFile=path;$('#file-title').textContent=path;$('#file-content').textContent=templates[activeTemplate].files[path];$$('.file-tree button').forEach(b=>{const s=b.dataset.file===path;b.classList.toggle('selected',s);b.setAttribute('aria-pressed',String(s));});}
function renderTemplate(name){activeTemplate=name;const t=templates[name];$('#workspace-title').textContent=t.title;$('#workspace-kind').textContent=name==='helper'?'FUTURE EXAMPLE':'IMPLEMENTED ARCHITECTURE';$('#template-description').textContent=t.description;$$('[data-template]').forEach(b=>{const s=b.dataset.template===name;b.classList.toggle('selected',s);b.setAttribute('aria-selected',String(s));b.tabIndex=s?0:-1;});$('#template-panel').setAttribute('aria-labelledby','tab-'+name);$('#file-tree').replaceChildren(...Object.keys(t.files).map(path=>{const b=document.createElement('button');b.textContent=path;b.dataset.file=path;b.addEventListener('click',()=>showFile(path));return b;}));$('#template-tags').replaceChildren(...t.tags.map(t=>{const span=document.createElement('span');span.textContent=t;return span;}));showFile(Object.keys(t.files)[0]);}
$$('[data-template]').forEach(b=>b.addEventListener('click',()=>renderTemplate(b.dataset.template)));

let flow='deploy';let stage=0;let timer=null;let deploymentRevision='r12';
function deploymentRoles(){return deploymentRevision==='r13'?'researcher, verifier':'researcher';}
const flows={
  deploy:[
    {short:'Select revision',hint:'Read three exports',label:'01 / SELECT',title:'Choose a specific adapter revision',description:'Read the exported Markdown, callable declarations, and optional role catalog. Internal knowledge organization can differ by method.',facts:['Repo as the unit','Role catalog may be empty'],file:'adapter / exports',output:()=>`adapter: ${deploymentRevision}\ncontext: ADAPTER.md\ntools:   declared Python callables\nagents:  agents/index.yaml\nroles:   ${deploymentRoles()}\n\nstatus: formal run not started`},
    {short:'Convert roles',hint:'Generate host settings',label:'02 / TRANSFORM',title:'Convert minimal roles into native definitions',description:'The integration reads names, descriptions, and instructions, then generates host files or launch settings. Models, tools, permissions, and budgets use effective host defaults.',facts:['Three role fields','Coding agents can assist conversion'],file:'bootstrap / generated definitions',output:()=>`source roles: ${deploymentRoles()}\nfields: name / description / instructions\ntarget: selected-host-profile\n\nNative configuration generated; loading not yet verified.\nadapter source revision: ${deploymentRevision}`},
    {short:'Prepare integration',hint:'Context and MCP',label:'03 / PREPARE',title:'Prepare context, tool connections, and resources',description:'Arrange Markdown injection, framework MCP launch, and native role locations. Preparation alone does not establish role availability.',facts:['Markdown → Host context','MCP → Tool service'],file:'bootstrap / prepared inputs',output:()=>`context: prepared\nmcp connection: configured\nagent definitions: generated\nresource bindings: prepared\n\nnext: start the target Acting Harness`},
    {short:'Start & verify',hint:'Confirm actual loading',label:'04 / LOAD & VERIFY',title:'Let the host load definitions, then verify readiness',description:'Start the Acting Harness and let its native loader read role settings. Confirm tools and roles work before formal tasks. v0 does not require hot loading.',facts:['The host owns loading','Files do not prove availability'],file:'bootstrap / availability checks',output:()=>`Acting Harness: started\nContext: available\nMCP tools: available\nnative roles: ${deploymentRoles()} / available\n\nchecks: PASS (UI simulation)`},
    {short:'Run tasks',hint:'Create instances as needed',label:'05 / ACT',title:'Fixed definitions, task-specific instances',description:'The parent agent starts its task and selects MCP tools or native roles as needed. The Acting Harness creates and runs child instances; task inputs can differ each time.',facts:['Definitions fixed for this run','The 4B helper remains a tool'],file:'run / ready',output:()=>`new run revision: ${deploymentRevision}\nloaded roles: ${deploymentRoles()}\nrole definitions: fixed for this run\n\nThe parent can delegate tasks to loaded roles.\nThe host creates instances on demand.`}
  ],
  evolve:[
    {short:'Collect experience',hint:'Keep the current run',label:'01 / EXPERIENCE',title:'Collect records available from the current run',description:'Collect calls, results, and feedback that the host actually exposes. Consumption interfaces do not grant full history access; experience collection needs its own integration.',facts:['Current run: r12','Role definitions unchanged'],file:'experience / current run',output:()=>`running: r12\nloaded roles: researcher\nrecords: available calls / results\nfeedback: optional\n\nThe Acting Harness continues to run tasks.`},
    {short:'Run learning',hint:'Use Meta Harness',label:'02 / LEARN',title:'The Evolver edits the candidate within its allowed scope',description:'The Evolver determines updates; the Meta Harness supports reading experience, editing, and checks. Methods retain their internal structures and learning processes.',facts:['Algorithm separate from execution','Isolated candidate workspace'],file:'meta / candidate workspace',output:()=>`base: r12\ncandidate: r13\nworkspace: isolated candidate repo\nevolver: selected method\nmeta harness: learner execution environment\n\nCandidate edits do not change the running r12.`},
    {short:'Produce candidate',hint:'Update three exports',label:'03 / CANDIDATE',title:'New roles start as candidate definitions',description:'This example updates Context and adds a verifier role with only a name, description, and instructions. Writing the candidate does not automatically add a role to the running Acting Harness.',facts:['Candidate: r13','Only original roles are running'],file:'candidate / changes',output:()=>`~ ADAPTER.md\n+ agents/verifier.md\n+ agents/index.yaml: verifier\n\nrequired fields:\n  name / description / instructions\n\nrunning r12 roles: researcher`},
    {short:'Check candidate',hint:'Validity versus utility',label:'04 / CHECK',title:'Check validity without claiming improved performance',description:'Check declarations, files, and method-specific tests. Measure performance when appropriate evaluation is available. This simulation shows checks passing, not a performance gain.',facts:['Passing checks is not improvement','Verify native loading in the next run'],file:'candidate / checks',output:()=>`export declarations: PASS\nagent definitions: PASS\nmethod checks: PASS\nperformance: NOT EVALUATED\n\nNo online verifier registration in the current host.`},
    {short:'Deliver revision',hint:'Wait for next deployment',label:'05 / NEXT REVISION',title:'Candidate ready, current roles unchanged',description:'The orchestrator makes r13 available for the next deployment. The host loads verifier at that boundary, using native configuration or optional helpers.',facts:['Current run remains r12','Next deployment uses r13'],file:'candidate / handoff',output:()=>`decision owner: ${mode==='cli'?'default-manager':'Reef'}\ncandidate r13: ready for next deployment\ncurrent run: r12\ncurrent roles: researcher\nnext roles: researcher, verifier\n\nNo in-place role replacement.`}
  ]
};
const nativePreparation = {
  1:{short:'Read interfaces',hint:'Use existing integration',label:'02 / NATIVE INTEGRATION',title:'The host or external integration reads the exports',description:'Use native host settings, manual configuration, or an external framework. This path does not invoke our Bootstrap / Connector.',facts:['Helper not enabled','Same consumption interfaces'],file:'integration / native route',output:()=>`context: core context output\ntools: core declarations → framework MCP\nagents: optional role definitions\n\nhandled_by: host / user / external framework\nhelper: not used`},
  2:{short:'Check settings',hint:'No built-in converter needed',label:'03 / PROVIDED CONFIGURATION',title:'Use the prepared host configuration',description:'The deployer or external framework has arranged context, MCP, and required native roles. The framework does not require regenerating or overwriting those settings.',facts:['Existing integration prepares inputs','No duplicate role installation'],file:'integration / provided settings',output:()=>`context entry: provided\nMCP connection: provided\nnative role configuration: provided\n\nVerify actual availability before formal tasks.`},
  3:{short:'Confirm readiness',hint:'Native loading ready',label:'04 / READINESS',title:'Confirm that the host loaded the required capabilities',description:'The native host mechanism loads roles. The actual integration verifies readiness without having to use our checker.',facts:['Integration owns verification','Role definitions fixed for the run'],file:'integration / ready',output:()=>`Context: available\nMCP tools: available\nnative roles: ${deploymentRoles()} / loaded by Acting Harness\n\nbootstrap helper: not required`}
};
function currentStages(){return flow==='deploy'&&$('#integration-path').value==='native'?flows.deploy.map((item,i)=>nativePreparation[i]||item):flows[flow];}
function stopDemo(){if(timer){clearInterval(timer);timer=null;}$('#play-demo').disabled=false;$('#play-demo').textContent=flow==='deploy'?'▶ Play deployment':'▶ Play evolution';}
function setFlow(name,revision='r12'){
  stopDemo();flow=name;deploymentRevision=revision;stage=0;
  $$('[data-flow]').forEach(b=>{const s=b.dataset.flow===name;b.classList.toggle('selected',s);b.setAttribute('aria-selected',String(s));b.tabIndex=s?0:-1;});$('#flow-panel').setAttribute('aria-labelledby','flow-tab-'+name);
  $('#integration-choice').hidden=name!=='deploy';const selectedStages=currentStages();$$('[data-step]').forEach((b,i)=>{b.querySelector('strong').textContent=selectedStages[i].short;b.querySelector('small').textContent=selectedStages[i].hint;});stopDemo();renderStage(0);
}
function renderStage(index){
  stage=index;const failed=$('#check-result').value==='fail';const d=currentStages()[index];let title=d.title,description=d.description,facts=d.facts,output=d.output();
  if(failed&&index>=3){
    if(flow==='deploy'){title=index===3?'Loading check failed; formal tasks are blocked':'Integration not ready; formal run not started';description='In this example, the host did not discover researcher. Retain diagnostics, fix the integration, and verify again. Generated files cannot substitute for successful registration.';facts=['Native role not loaded','Integration needs correction'];output=`Context: available\nMCP tools: available\nresearcher: NOT AVAILABLE\n\nintegration: failed\nformal run: not started\ntarget revision: ${deploymentRevision}`;}
    else{title=index===3?'Candidate checks failed; retain diagnostics':'Candidate rejected; current run stays on r12';description='The candidate role references a missing instructions file. The Evolver can revise it; the orchestrator does not hand it to the next formal deployment.';facts=['r13 not ready','Running r12 unchanged'];output='candidate r13: rejected\nreason: missing instructions file\ncurrent run: r12\nloaded roles: researcher\n\nReturn diagnostics to the Evolver.';}
  }
  const ready=flow==='deploy'&&index===4&&!failed;
  $('#run-label').textContent=flow==='deploy'?'New run':'Current run';$('#active-revision').textContent=flow==='evolve'?'r12':ready?deploymentRevision:'Not started';
  $('#revision-label').textContent=flow==='evolve'?(index===4&&!failed?'r13 awaits next deployment':'Candidate edits leave current roles unchanged'):`Target: adapter ${deploymentRevision}`;
  $('#step-eyebrow').textContent=d.label;$('#step-title').textContent=title;$('#step-description').textContent=description;$('#console-title').textContent=d.file;$('#step-output').textContent=output;
  $('#step-facts').replaceChildren(...facts.map(t=>{const e=document.createElement('span');e.textContent=t;return e;}));
  $$('[data-step]').forEach(b=>{const n=Number(b.dataset.step);b.classList.toggle('current',n===index);b.classList.toggle('done',n<index);if(n===index)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});
  $('#next-bootstrap').disabled=!(flow==='evolve'&&index===4&&!failed);
}
$$('[data-flow]').forEach(b=>b.addEventListener('click',()=>setFlow(b.dataset.flow)));
$('#integration-path').addEventListener('change',()=>setFlow('deploy',deploymentRevision));
$('#play-demo').addEventListener('click',()=>{stopDemo();renderStage(0);$('#play-demo').disabled=true;$('#play-demo').textContent='Playing…';timer=setInterval(()=>{renderStage(stage+1);if(stage===4)stopDemo();},1100);});
$('#reset-demo').addEventListener('click',()=>{stopDemo();renderStage(0);});$('#check-result').addEventListener('change',()=>{stopDemo();renderStage(0);});
$$('[data-step]').forEach(b=>b.addEventListener('click',()=>{stopDemo();renderStage(Number(b.dataset.step));}));
$('#next-bootstrap').addEventListener('click',()=>{setFlow('deploy','r13');toast('Prepare the next deployment; do not replace current roles');});

const entries={
 cli:{label:'FOR ADAPTER USERS',title:'The CLI organizes deployment and evolution.',description:'Start with an adapter repo or architecture. Use native/external integration or optional helpers. New role definitions load at the next startup.',items:['Shared infrastructure for repo, tool, and role integration','Meta Harness supports the chosen Evolver','Fixed roles now; new definitions next run'],filename:'terminal · current local prototype',code:"# Prepare and open either acting host\n./harnessadapter mwm --codex\n./harnessadapter mwm --claude\n\n# Real model call; produces a separate candidate\n./harnessadapter evolve mwm \\\n  --evidence fixtures/mwm_evidence\n\n# The reported candidate can be loaded like any core\n./harnessadapter /path/to/session/adapter --codex\n\n# No automatic activation; inspect the candidate first."},
 reef:{label:'FOR FRAMEWORK AUTHORS',title:'Reef retains update orchestration.',description:'External frameworks call preparation and evolution through the same SDK. They own experience selection, evaluation, and release; their integration handles candidate representations and deployment.',items:['Adapt host integration and framework orchestration separately','The same adapter still exposes three exports','No requirement to use the default Manager'],filename:'reef_bridge.py · proposed integration',code:'# Conceptual pseudocode, not a runnable Reef plugin\n# Optional: skip if integration is already available\nprepared = sdk.prepare(adapter, target_host)\n# The framework starts the host, verifies, and runs tasks\n\ndef propose(nodes, samples, models):\n    candidate = sdk.evolve(\n        workspace=adapter_workspace,\n        evidence=bridge.import_samples(samples),\n        resources=bridge.bind_models(models),\n        evolver="mwm",\n    )\n    return bridge.to_mutations(candidate)\n\n# Reef selects candidates and arranges the next deployment.'}
};
let entry='cli';
function renderEntry(name,sync=true){entry=name;const d=entries[name];$$('[data-entry]').forEach(b=>{const s=b.dataset.entry===name;b.classList.toggle('selected',s);b.setAttribute('aria-selected',String(s));b.tabIndex=s?0:-1;});$('#entry-panel').setAttribute('aria-labelledby','entry-tab-'+name);$('#entry-label').textContent=d.label;$('#entry-title').textContent=d.title;$('#entry-description').textContent=d.description;$('#entry-filename').textContent=d.filename;$('#entry-code').textContent=d.code;$('#entry-list').replaceChildren(...d.items.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));if(sync&&mode!==name)setMode(name);}
$$('[data-entry]').forEach(b=>b.addEventListener('click',()=>renderEntry(b.dataset.entry)));

$$('[role="tablist"]').forEach(list=>list.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...list.querySelectorAll('[role="tab"]')];let i=tabs.indexOf(document.activeElement);if(i<0)return;e.preventDefault();i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();tabs[i].click();}));
let toastTimeout;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied');}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'Copied':'Clipboard unavailable; select and copy the example text');}}
$('#copy-file').addEventListener('click',()=>copy(templates[activeTemplate].files[activeFile]));$('#copy-entry').addEventListener('click',()=>copy(entries[entry].code));
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');});
$$('.nav-link').forEach(a=>a.addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
const sections=$$('main section[id]');let scrolling=false;
function updateNav(){const active=[...sections].reverse().find(s=>s.getBoundingClientRect().top<180)||sections[0];$$('.nav-link').forEach(a=>{const selected=a.hash==='#'+active.id;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});scrolling=false;}
window.addEventListener('scroll',()=>{if(!scrolling){scrolling=true;requestAnimationFrame(updateNav);}},{passive:true});
renderTemplate('knowledge');setFlow('deploy');setMode('cli');updateNav();

// This is a configuration preview, never a live permission change.
function renderPolicy(){
  const backend=$('#policy-backend').value;
  const readMode=$('#policy-read-mode').value;
  const online=$('#policy-network').checked;
  const path=$('#policy-read-path').value;
  $('#policy-path-label').hidden=readMode!=='directory';
  $('#policy-environment-read').textContent=readMode==='all'?'All paths':readMode==='directory'?'Selected directory':'Not granted';
  $('#policy-network-note').textContent=online?'Network: enabled. Filesystem write scope stays unchanged.':'Network: blocked for tools and commands. Model inference remains connected.';
  const prefix='backend = '+JSON.stringify(backend)+'\nnetwork = '+online+'\n';
  const reads=readMode==='all'?'read_access = "all"\n':'\n[read_access]\npaths = '+JSON.stringify(readMode==='directory'?[path]:[])+'\n';
  $('#policy-config').textContent=prefix+reads;
}
['policy-backend','policy-read-mode','policy-network','policy-read-path'].forEach(id=>$('#'+id).addEventListener('input',renderPolicy));
$('#copy-policy').addEventListener('click',()=>copy($('#policy-config').textContent));
renderPolicy();

// Concept preview only: no model calls or persistence are performed here.
document.querySelectorAll('[data-training-state]').forEach(button => {
  button.addEventListener('click', () => {
    const stateful = button.dataset.trainingState === 'stateful';
    document.querySelectorAll('[data-training-state]').forEach(item => {
      const selected = item === button;
      item.classList.toggle('selected', selected);
      item.setAttribute('aria-pressed', String(selected));
    });
    document.querySelectorAll('.training-state-input').forEach(item => { item.hidden = !stateful; });
    document.querySelector('#training-state-output').classList.toggle('inactive', !stateful);
    const title = document.querySelector('#training-state-title');
    title.replaceChildren(document.createTextNode(stateful ? 'Training State ' : 'None'));
    if (stateful) { const time = document.createElement('small'); time.textContent = 't + 1'; title.append(time); }
    document.querySelector('#training-state-description').textContent = stateful ? 'Search history, candidates & progress.' : 'No optimizer state to save or restore.';
    document.querySelector('#training-state-destination').textContent = stateful ? 'Resume the next iteration ↻' : 'training_state = None';
    document.querySelector('#training-mode-note').textContent = stateful ? 'Stateful Evolvers return separate training state. Acting agents only need the Adapter.' : 'Stateless Evolvers return an Adapter and no training state. They can still learn from supplied experience.';
  });
});
